mapper.select:
select b.contract_code contractCode from contract_base_info b where b.id in (select distinct contract_id from contract_pledge a where
json_contains(a.pledge_ids, CONVERT(#{item},CHAR))
) and b.contract_status != "INVALID" and b.contract_code is not null
and b.id != #{contractId}
and b.contract_code like CONCAT('%',#{code},'%')
